const item = $input.item.json ?? {};

// Get today's date (start of day)
const today = new Date();
today.setHours(0, 0, 0, 0);

// Read raw date strings (exact column names)
const dueDateString = item['Due Date'];
const invoiceDateString = item['Invoice Date '];

let daysOverdue = null;
let dueDateFormatted = null;
let invoiceDateFormatted = null;

// -------- DUE DATE (MM/DD/YYYY) --------
if (typeof dueDateString === 'string' && dueDateString.includes('/')) {
  const parts = dueDateString.split('/');

  if (parts.length === 3) {
    const month = parseInt(parts[0], 10) - 1; // MM
    const day = parseInt(parts[1], 10);       // DD
    const year = parseInt(parts[2], 10);      // YYYY

    const dueDate = new Date(year, month, day);

    if (!isNaN(dueDate.getTime())) {
      dueDate.setHours(0, 0, 0, 0);
      const diff = today - dueDate;
      daysOverdue = Math.floor(diff / (1000 * 60 * 60 * 24));

      // Format MM/DD/YYYY
      dueDateFormatted = `${String(month + 1).padStart(2, '0')}/${String(day).padStart(2, '0')}/${year}`;
    }
  }
}

// -------- INVOICE DATE (MM/DD/YYYY) --------
if (typeof invoiceDateString === 'string' && invoiceDateString.includes('/')) {
  const parts = invoiceDateString.split('/');

  if (parts.length === 3) {
    const month = parseInt(parts[0], 10) - 1;
    const day = parseInt(parts[1], 10);
    const year = parseInt(parts[2], 10);

    const invoiceDate = new Date(year, month, day);

    if (!isNaN(invoiceDate.getTime())) {
      invoiceDateFormatted = `${String(month + 1).padStart(2, '0')}/${String(day).padStart(2, '0')}/${year}`;
    }
  }
}

// ✅ RETURN SINGLE OBJECT (correct for Run Once for Each Item)
return {
  json: {
    ...item,
    daysOverdue,
    currentDate: today.toISOString().split('T')[0],
    dueDateFormatted: dueDateFormatted || dueDateString,
    invoiceDateFormatted: invoiceDateFormatted || invoiceDateString,
    row_number: item.row_number ?? null
  }
};

